static const GUID tnFloat={3,0,0x10,{0x80,0,0,0xaa,0,0x38,0x9b,0x71}};
static const GUID tnPcm={1,0,0x10,{0x80,0,0,0xaa,0,0x38,0x9b,0x71}};
static float TnMono(const BYTE*p,const WAVEFORMATEX*f)
{
	if(!p||!f)return 0;int ch=f->nChannels,b=f->wBitsPerSample;float l=0,r=0;
	BOOL fl=f->wFormatTag==WAVE_FORMAT_IEEE_FLOAT||(f->wFormatTag==WAVE_FORMAT_EXTENSIBLE&&b==32&&((WAVEFORMATEXTENSIBLE*)f)->SubFormat==tnFloat);
	BOOL pc=f->wFormatTag==WAVE_FORMAT_PCM||(f->wFormatTag==WAVE_FORMAT_EXTENSIBLE&&((WAVEFORMATEXTENSIBLE*)f)->SubFormat==tnPcm);
	if(fl){const float*q=(const float*)p;l=q[0];r=ch>1?q[1]:l;}else if(pc&&b==16){const short*q=(const short*)p;l=q[0]/32768.f;r=ch>1?q[1]/32768.f:l;}else if(pc&&b==24){int x=p[0]|p[1]<<8|p[2]<<16;if(x&0x800000)x|=~0xffffff;l=x/8388608.f;if(ch>1){p+=3;x=p[0]|p[1]<<8|p[2]<<16;if(x&0x800000)x|=~0xffffff;r=x/8388608.f;}else r=l;}else if(pc&&b==32){const int*q=(const int*)p;l=q[0]/2147483648.f;r=ch>1?q[1]/2147483648.f:l;}return(l+r)*.5f;
}
