void CTnNeedlePanel::OnPaint(){CPaintDC dc(this);CRect r;GetClientRect(r);CDC mem;mem.CreateCompatibleDC(&dc);CBitmap b;b.CreateCompatibleBitmap(&dc,max(1,r.Width()),max(1,r.Height()));CBitmap*o=mem.SelectObject(&b);mem.FillSolidRect(r,RGB(245,245,248));int cy=r.CenterPoint().y;mem.FillSolidRect(5,cy,r.Width()-10,1,RGB(130,130,140));int x=5+(r.Width()-10)*(m_cents+100)/200;CPen pen(PS_SOLID,2,abs(m_cents)<=5?RGB(35,160,70):RGB(210,90,40));CPen*op=mem.SelectObject(&pen);mem.MoveTo(x,3);mem.LineTo(x,r.bottom-3);mem.SelectObject(op);dc.BitBlt(0,0,r.Width(),r.Height(),&mem,0,0,SRCCOPY);mem.SelectObject(o);}

