BOOL CTunerPracticeDlg::PreTranslateMessage(MSG*p){if(m_tooltip.GetSafeHwnd())m_tooltip.RelayEvent(p);return CCustomBlurDialogBase::PreTranslateMessage(p);}void CTunerPracticeDlg::PostNcDestroy(){CCustomBlurDialogBase::PostNcDestroy();if(g_tn==this)g_tn=NULL;delete this;}void CTunerPracticeDlg::LayoutHelpBtn(){CCC_CaptionPlaceHelpBtn(m_hWnd,&m_help);}
void CTunerPracticeDlg::FillDevices(){AudioMicDevRefresh();m_mic.ResetContent();m_micCnt=0;int sel=0;for(int i=0;i<AudioMicDevCount()&&m_micCnt<TN_MAX;i++){LPCTSTR id=AudioMicDevId(i);if(!id||!*id)continue;_tcsncpy(m_micIds[m_micCnt],id,255);m_micIds[m_micCnt][255]=0;m_mic.AddString(AudioMicDevName(i));if(!_tcsicmp(id,savedata.tn_mic_device))sel=m_micCnt;m_micCnt++;}if(m_micCnt)m_mic.SetCurSel(sel);AudioLoopDevRefresh();m_out.ResetContent();m_outCnt=0;sel=0;for(int i=0;i<AudioLoopDevCount()&&m_outCnt<TN_MAX;i++){LPCTSTR id=AudioLoopDevId(i);if(!id||!*id)continue;_tcsncpy(m_outIds[m_outCnt],id,255);m_outIds[m_outCnt][255]=0;m_out.AddString(AudioLoopDevName(i));if(!_tcsicmp(id,savedata.tn_out_device))sel=m_outCnt;m_outCnt++;}if(m_outCnt)m_out.SetCurSel(sel);}
void CTunerPracticeDlg::FillValues(){for(int v=40;v<=240;v+=5){CString x;x.Format(L"%d",v);m_bpm.AddString(x);if(v==savedata.tn_bpm)m_bpm.SetCurSel(m_bpm.GetCount()-1);}if(m_bpm.GetCurSel()<0)m_bpm.SetCurSel(16);for(int v=2;v<=8;v++){CString x;x.Format(L"%d",v);m_beats.AddString(x);if(v==savedata.tn_beats)m_beats.SetCurSel(v-2);}if(m_beats.GetCurSel()<0)m_beats.SetCurSel(2);for(int v=430;v<=450;v++){CString x;x.Format(L"%d Hz",v);m_a4.AddString(x);if(v==savedata.tn_a4_hz)m_a4.SetCurSel(v-430);}if(m_a4.GetCurSel()<0)m_a4.SetCurSel(10);m_mute.SetCheck(savedata.tn_mute?BST_CHECKED:BST_UNCHECKED);}
void CTunerPracticeDlg::PersistUi(){int i=m_mic.GetCurSel();if(i>=0&&i<m_micCnt)_tcsncpy(savedata.tn_mic_device,m_micIds[i],255);savedata.tn_mic_device[255]=0;i=m_out.GetCurSel();if(i>=0&&i<m_outCnt)_tcsncpy(savedata.tn_out_device,m_outIds[i],255);savedata.tn_out_device[255]=0;savedata.tn_bpm=40+max(0,m_bpm.GetCurSel())*5;savedata.tn_beats=2+max(0,m_beats.GetCurSel());savedata.tn_a4_hz=430+max(0,m_a4.GetCurSel());savedata.tn_mute=m_mute.GetCheck()==BST_CHECKED;m_bpmVal=savedata.tn_bpm;m_beatsVal=savedata.tn_beats;m_a4Val=savedata.tn_a4_hz;MpPersistSavedataQuick();}
