void CTunerPracticeDlg::StartAudio(){StopAudio();InterlockedExchange(&m_stop,0);InterlockedExchange(&m_lastHr,S_OK);uintptr_t t=_beginthreadex(NULL,0,AudioThread,this,0,NULL);if(t)m_thread=(HANDLE)t;m_nextClickTick=GetTickCount()+100;m_status.SetWindowText(LL14(L"単音をマイクへ入力してください。",L"Play a single note into the microphone.",L"Jouez une note dans le micro.",L"Suona una nota nel microfono.",L"Toque una nota al micrófono.",L"마이크에 단음을 입력하세요.",L"请向麦克风输入单音。",L"اعزف نغمة واحدة في الميكروفون.",L"Подайте одну ноту в микрофон.",L"Spielen Sie einen Einzelton ins Mikrofon.",L"Toque uma nota no microfone.",L"Speel één noot in de microfoon.",L"Zagraj pojedynczy dźwięk do mikrofonu.",L"Mikrofona tek nota çalın."));}
void CTunerPracticeDlg::StopAudio(){InterlockedExchange(&m_stop,1);if(m_thread){WaitForSingleObject(m_thread,4000);CloseHandle(m_thread);m_thread=NULL;}InterlockedExchange(&m_run,0);}
void CTunerPracticeDlg::OnClick(){if(!savedata.tn_mute)InterlockedExchange(&m_clickRequest,2);}
