void CTunerPracticeDlg::OnTimer(UINT_PTR id){if(id==TN_TIMER){DWORD now=GetTickCount();if((LONG)(now-m_nextClickTick)>=0){m_beat=(m_beat+1)%max(2,m_beatsVal);if(!savedata.tn_mute)InterlockedExchange(&m_clickRequest,m_beat==0?2:1);m_nextClickTick=now+60000/max(40,m_bpmVal);}LONG hz=InterlockedCompareExchange(&m_hz100,0,0),ce=InterlockedCompareExchange(&m_cent100,0,0);if(hz>0){double f=hz/100.0;int midi=(int)floor(69+12*log(f/m_a4Val)/log(2.0)+.5);static LPCTSTR names[]={L"C",L"C#",L"D",L"D#",L"E",L"F",L"F#",L"G",L"G#",L"A",L"A#",L"B"};CString n;n.Format(L"%s%d",names[(midi%12+12)%12],midi/12-1);m_note.SetWindowText(n);int cents=max(-100,min(100,(int)(ce/100)));CString c;c.Format(L"%+d cent",cents);m_cents.SetWindowText(c);m_needle.SetCents(cents);}}CCustomBlurDialogBase::OnTimer(id);}
UINT __stdcall CTunerPracticeDlg::AudioThread(void*q){CTunerPracticeDlg*s=(CTunerPracticeDlg*)q;CoInitializeEx(NULL,COINIT_MULTITHREADED);IMMDeviceEnumerator*e=NULL;IMMDevice*mi=NULL,*od=NULL;IAudioClient*cc=NULL,*rc=NULL;IAudioCaptureClient*cp=NULL;IAudioRenderClient*rr=NULL;WAVEFORMATEX*f=NULL;UINT32 rb=0;HRESULT h=CoCreateInstance(__uuidof(MMDeviceEnumerator),NULL,CLSCTX_ALL,__uuidof(IMMDeviceEnumerator),(void**)&e);if(SUCCEEDED(h))h=e->GetDevice(savedata.tn_mic_device,&mi);if(FAILED(h)&&e)h=e->GetDefaultAudioEndpoint(eCapture,eConsole,&mi);if(SUCCEEDED(h))h=mi->Activate(__uuidof(IAudioClient),CLSCTX_ALL,NULL,(void**)&cc);if(SUCCEEDED(h))h=cc->GetMixFormat(&f);if(SUCCEEDED(h))h=cc->Initialize(AUDCLNT_SHAREMODE_SHARED,AUDCLNT_STREAMFLAGS_NOPERSIST,2000000,0,f,NULL);if(SUCCEEDED(h))h=cc->GetService(__uuidof(IAudioCaptureClient),(void**)&cp);if(SUCCEEDED(h))h=e->GetDevice(savedata.tn_out_device,&od);if(FAILED(h)&&e)h=e->GetDefaultAudioEndpoint(eRender,eConsole,&od);WAVEFORMATEX rf={WAVE_FORMAT_PCM,2,48000,192000,4,16,0};if(SUCCEEDED(h))h=od->Activate(__uuidof(IAudioClient),CLSCTX_ALL,NULL,(void**)&rc);if(SUCCEEDED(h))h=rc->Initialize(AUDCLNT_SHAREMODE_SHARED,0,2000000,0,&rf,NULL);if(SUCCEEDED(h))h=rc->GetBufferSize(&rb);if(SUCCEEDED(h))h=rc->GetService(__uuidof(IAudioRenderClient),(void**)&rr);if(SUCCEEDED(h)){h=cc->Start();if(SUCCEEDED(h))h=rc->Start();}InterlockedExchange(&s->m_lastHr,h);if(FAILED(h))goto done;InterlockedExchange(&s->m_run,1);{float ring[8192]={};int w=0;DWORD last=0;while(!InterlockedCompareExchange(&s->m_stop,0,0)){UINT32 n=0;if(SUCCEEDED(cp->GetNextPacketSize(&n))&&n){BYTE*d=NULL;DWORD fl=0;if(SUCCEEDED(cp->GetBuffer(&d,&n,&fl,NULL,NULL))){for(UINT32 i=0;i<n;i++)ring[w++&8191]=(fl&AUDCLNT_BUFFERFLAGS_SILENT)?0:TnMono(d+(SIZE_T)i*f->nBlockAlign,f);cp->ReleaseBuffer(n);}}LONG click=InterlockedExchange(&s->m_clickRequest,0);if(click){UINT32 pad=0;rc->GetCurrentPadding(&pad);UINT32 n=min((UINT32)960,rb>pad?rb-pad:0);BYTE*b=NULL;if(n&&SUCCEEDED(rr->GetBuffer(n,&b))){short*p=(short*)b;double fr=click==2?1760.0:1320.0;for(UINT32 i=0;i<n;i++){double env=1.0-(double)i/n;short v=(short)(sin(6.283185307*fr*i/48000.0)*env*15000);p[i*2]=p[i*2+1]=v;}rr->ReleaseBuffer(n,0);}}DWORD now=GetTickCount();if(w>4096&&now-last>150){last=now;float mean=0,energy=0;for(int i=0;i<4096;i++){float x=ring[(w-4096+i)&8191];mean+=x;}mean/=4096;for(int i=0;i<4096;i++){float x=ring[(w-4096+i)&8191]-mean;energy+=x*x;}if(energy>.001f){int minLag=max(20,(int)f->nSamplesPerSec/1200),maxLag=min(1600,(int)f->nSamplesPerSec/45),best=0;double bc=0;for(int lag=minLag;lag<=maxLag;lag++){double c=0,a=0,b=0;for(int i=lag;i<4096;i+=2){float x=ring[(w-4096+i)&8191]-mean,y=ring[(w-4096+i-lag)&8191]-mean;c+=x*y;a+=x*x;b+=y*y;}double z=c/sqrt(a*b+1e-20);if(z>bc){bc=z;best=lag;}}if(best&&bc>.55){double hz=(double)f->nSamplesPerSec/best,midi=69+12*log(hz/s->m_a4Val)/log(2.0),cent=(midi-floor(midi+.5))*100;InterlockedExchange(&s->m_hz100,(LONG)(hz*100));InterlockedExchange(&s->m_cent100,(LONG)(cent*100));}}}Sleep(2);}}done:if(cc)cc->Stop();if(rc)rc->Stop();if(rr)rr->Release();if(cp)cp->Release();if(rc)rc->Release();if(cc)cc->Release();if(od)od->Release();if(mi)mi->Release();if(e)e->Release();if(f)CoTaskMemFree(f);InterlockedExchange(&s->m_run,0);CoUninitialize();return 0;}
void CTunerPracticeDlg::ShowHelpSheet(){if(tnHelp&&tnHelp->GetSafeHwnd()){tnHelp->SetForegroundWindow();return;}tnHelp=new CTnHelp(this);if(!tnHelp->Create(IDD_TN_HELP,this)){delete tnHelp;tnHelp=NULL;return;}CCC_PresentOwnedHelp(this,tnHelp);}void CTunerPracticeDlg::OnHelp(){ShowHelpSheet();}void CTunerPracticeDlg::OnCloseBtn(){DestroyWindow();}void CTunerPracticeDlg::OnOK(){}void CTunerPracticeDlg::OnCancel(){DestroyWindow();}void CTunerPracticeDlg::OnSize(UINT t,int x,int y){CCustomBlurDialogBase::OnSize(t,x,y);if(GetSafeHwnd()){CCC_CaptionLayout(m_hWnd);LayoutHelpBtn();}}void CTunerPracticeDlg::OnDestroy(){KillTimer(TN_TIMER);PersistUi();StopAudio();CCustomBlurDialogBase::OnDestroy();}
